import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out));
        int n = sc.nextInt();

        long[][] a = new long[n + 1][n + 1];
        long[][] b = new long[n + 1][n + 1];

        for (int sum = 2 * n; sum >= 0; sum--) {
            for (int i = 0; i <= n; i++) {
                int j = sum - i;
                if (j < 0 || j > i) continue;
                if (i == n && j == n) continue;

                if (i == j) {
                    a[i][j] = Math.max(1 + b[i + 1][j], a[i + 1][j]);
                    b[i][j] = a[i + 1][j];
                } else if (i == n) {
                    a[i][j] = Math.max(1 + b[i][j + 1], a[i][j + 1]);
                    b[i][j] = a[i][j + 1];
                } else {
                    long downA = a[i + 1][j];
                    long rightA = a[i][j + 1];
                    long downB = b[i + 1][j];
                    long rightB = b[i][j + 1];
                    long v1 = (downA + rightA) % MOD;
                    long v2 = (1 + downB + rightA) % MOD;
                    long v3 = (1 + downA + rightB) % MOD;
                    a[i][j] = Math.max(v1, Math.max(v2, v3));
                    b[i][j] = v1;
                }
            }
        }

        pw.println(a[0][0] % MOD);
        pw.close();
    }

    static class Scanner {
        StringTokenizer st;
        BufferedReader br;

        public Scanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        public boolean ready() throws IOException {
            return br.ready();
        }
    }
}
